@Timeout(60)
class LmdbBackupOutboxLayoutTest {

	@Test
	void boundedFallbackStageBacklogAvoidsNativeBranchPages(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile(),
				new LmdbStoreConfig().setBackupJournalEnabled(true));
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		store.init();
		try {
			long baseline = store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.FULL).build())
					.getEndTransactionId();
			TripleStore triples = store.getBackingStore().getTripleStore();
			UUID predecessor = triples.getBackupOutboxHead();
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			publisher.setBeforePublication(() -> {
				entered.countDown();
				try {
					if (!release.await(40, TimeUnit.SECONDS)) {
						throw new AssertionError("The test did not release the bounded backup backlog");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError(interrupted);
				}
			});
			add(store, 0);
			assertTrue(entered.await(20, TimeUnit.SECONDS), "The first stage must pause before publication");
			for (int i = 1; i <= 128; i++) {
				add(store, i);
			}
			long head = baseline + 129;
			List<Long> expected = LongStream.rangeClosed(baseline + 1, head).boxed().toList();
			assertEquals(expected, triples.listBackupStageTransactions(baseline, Long.MAX_VALUE),
					"A blocked publisher must retain every committed source stage");
			assertEquals(head, triples.getRequiredBackupTxnId());
			for (long transaction : expected) {
				LmdbBackupFallbackTestSupport.assertStripedFrame(triples, transaction);
				byte[] header = triples.readBackupStageHeader(transaction);
				assertNotNull(header, "Every retained transaction must have an authoritative stage header");
				try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(header))) {
					var stage = PostCommitBackupPublisher.readStage(input, null);
					assertEquals(transaction, stage.transaction);
					assertEquals(transaction - 1, stage.previousTransaction);
					assertEquals(predecessor, stage.predecessor);
					assertEquals(1, stage.count);
					predecessor = stage.id;
				}
			}
			assertEquals(predecessor, triples.getBackupOutboxHead());
			Map<String, Long> branchPages = outboxBranchPages(triples);
			assertFalse(branchPages.isEmpty(), "Committed stages must reside in at least one native outbox database");
			assertEquals(0L, branchPages.values().stream().mapToLong(Long::longValue).sum(),
					() -> "A bounded backlog of striped fallback stages must not add outbox branch pages: "
							+ branchPages);
			release.countDown();
			assertEquals(head, store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(baseline)
							.build())
					.getEndTransactionId());
			assertEquals(expected, ((LmdbBackupServiceImpl) store.getBackupService())
					.publishedTransactionIds(backups, baseline, head));
		} finally {
			release.countDown();
			store.shutDown();
		}
	}

	private static Map<String, Long> outboxBranchPages(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBStat catalogStatistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, database.get(0), catalogStatistics));
			assertEquals(1, catalogStatistics.ms_depth(),
					"Outbox databases must not move their branch-page cost into the main catalog");
			var handle = stack.mallocPointer(1);
			E(mdb_cursor_open(transaction, database.get(0), handle));
			long cursor = handle.get(0);
			try {
				Map<String, Long> branchPages = new LinkedHashMap<>();
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack);
				MDBStat statistics = MDBStat.malloc(stack);
				int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (result == MDB_SUCCESS) {
					String name = StandardCharsets.UTF_8.decode(Objects.requireNonNull(key.mv_data()).duplicate())
							.toString();
					if (name.startsWith("backup-outbox")) {
						E(mdb_dbi_open(transaction, name, 0, database));
						E(mdb_stat(transaction, database.get(0), statistics));
						branchPages.put(name, statistics.ms_branch_pages());
					}
					result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				E(result);
				return branchPages;
			} finally {
				mdb_cursor_close(cursor);
			}
		});
	}

	private static void add(LmdbStore store, int ordinal) {
		var values = SimpleValueFactory.getInstance();
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(values.createIRI("urn:s:" + ordinal), values.createIRI("urn:p"),
					values.createLiteral(LmdbBackupFallbackTestSupport.label("stage-" + ordinal)));
			connection.commit();
		}
	}
}
